#[test]
fn every_transfer_matches_colour_science() {
    for (e, want) in TRANSFERS {
        for (i, w) in want.iter().enumerate() {
            let s = i as f32 / 20.0;
            let got = e.light_f32(s) as f64;
            let tol = 2e-4 * w.abs().max(1.0) + 1e-6;
            assert!((got - w).abs() <= tol, "{} at {s}: {got} vs {w}", e.as_str());
        }
    }
}

/// VSF_RGB2XYZ × (primaries → VSF RGB) is the primaries' own RGB→XYZ: the matrices are colorimetric, thru 1931 XYZ, no adaptation.
#[test]
fn every_primaries_matrix_matches_colour_science() {
    for (p, npm) in PRIMARIES_TO_XYZ {
        let to_vsf = p.to_vsf_rgb().unwrap();
        for col in 0..3 {
            let mut unit = [0f32; 3];
            unit[col] = 1.0;
            let xyz = apply_matrix_3x3_f32(&vsf::colour::VSF_RGB2XYZ, &apply_matrix_3x3_f32(&to_vsf, &unit));
            for row in 0..3 {
                let want = npm[row * 3 + col];
                assert!((xyz[row] as f64 - want).abs() < 2e-4, "{} column {col} row {row}: {} vs {want}", p.as_str(), xyz[row]);
            }
        }
    }
}

#[test]
fn aliases_read_as_the_space_they_are() {
    assert_eq!(Primaries::parse("f_gamut").unwrap(), Primaries::Rec2020);
    assert_eq!(Primaries::parse("n_gamut").unwrap(), Primaries::Rec2020);
    assert_eq!(Primaries::parse("s_gamut").unwrap(), Primaries::SGamut3);
    assert_eq!(Primaries::SGamut3.as_str(), "s_gamut3");
}
